args.CommandLine:
@'
/* ============================================================
   EDITORIAL CINEMATIC THEME  (index_2.html + dashboard_2.html)
   Display : Instrument Serif 400   |  Body/UI : Inter 400/500
   Palette : Navy #0f172a, Black #000, White #fff
   Muted   : hsl(215,25%,32%)       |  Fallback bg: hsl(201,100%,13%)
   Scoped to body.ed-story / body.ed-dash so the original
   index.html / dashboard.html stay untouched.
   ============================================================ */

body.ed-story,
body.ed-dash {
  --font-primary: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-serif: 'Instrument Serif', Georgia, serif;
  --font-cursive: 'Instrument Serif', Georgia, serif;
  --font-mono: 'Geist Mono', ui-monospace, monospace;

  --bg-primary: #ffffff;
  --bg-paper: #ffffff;
  --bg-card: #ffffff;
  --bg-surface: #ffffff;
  --bg-sage: #f1f5f9;
  --bg-lavender: #e2e8f0;
  --bg-peach: #f1f5f9;

  --accent-coral: #0f172a;
  --accent-coral-hover: #1e293b;
  --accent-coral-deep: #0f172a;
  --accent-sage-deep: #334155;
  --accent-lavender-deep: #334155;
  --emerald: #0f172a;

  --text-dark: #0f172a;
  --text-muted: hsl(215, 25%, 32%);
  --text-subtle: hsl(215, 16%, 47%);

  --border-soft: rgba(15, 23, 42, 0.10);
  --border-medium: rgba(15, 23, 42, 0.20);
  --shadow-soft: 0 1px 2px rgba(15, 23, 42, 0.04), 0 10px 28px -14px rgba(15, 23, 42, 0.12);
  --shadow-hover: 0 2px 4px rgba(15, 23, 42, 0.05), 0 18px 40px -16px rgba(15, 23, 42, 0.20);
  --radius-container: 20px;
  --radius-card: 16px;

  font-family: var(--font-primary);
  color: var(--text-dark);
  background: #ffffff;
  -webkit-font-smoothing: antialiased;
}

body.ed-story .grain-overlay,
body.ed-dash .grain-overlay { display: none; }

/* ---------- Entrance: fade-rise (0.8s ease-out, 200ms stagger) ---------- */
@keyframes fadeRise {
  from { opacity: 0; transform: translateY(24px); }
  to   { opacity: 1; transform: translateY(0); }
}
.fade-rise {
  opacity: 0;
  animation: fadeRise 0.8s ease-out forwards;
}
.fade-rise.d0 { animation-delay: 0s; }
.fade-rise.d1 { animation-delay: 0.2s; }
.fade-rise.d2 { animation-delay: 0.4s; }
.fade-rise.d3 { animation-delay: 0.6s; }

/* ---------- Pill Action Button ---------- */
.pill-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 0;
  border-radius: 9999px;
  background: #000000;
  color: #ffffff;
  font-family: 'Inter', sans-serif;
  font-weight: 500;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  transition: transform 200ms ease-in-out, box-shadow 200ms ease-in-out;
}
.pill-btn:hover { transform: scale(1.03); box-shadow: 0 10px 28px -8px rgba(0, 0, 0, 0.45); }
.pill-btn.sm   { padding: 10px 24px; font-size: 14px; }
.pill-btn.hero { padding: 20px 56px; font-size: 16px; }
.pill-btn.ghost {
  background: rgba(255, 255, 255, 0.7);
  color: #0f172a;
  border: 1px solid rgba(15, 23, 42, 0.18);
  backdrop-filter: blur(10px);
}

/* ============================================================
   STORY NAVIGATION  (3-column grid, max 1280, px32, py24)
   ============================================================ */
body.ed-story .nav-wrapper,
body.ed-story .nav-wrapper.at-bottom,
body.ed-story .nav-wrapper.at-top {
  top: 0;
  left: 0;
  transform: none;
  width: 100%;
  max-width: none;
}
body.ed-story .nav-wrapper { transition: background 300ms ease, box-shadow 300ms ease; }
body.ed-story .nav-wrapper.at-top {
  background: rgba(255, 255, 255, 0.82);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  box-shadow: 0 1px 0 rgba(15, 23, 42, 0.08);
}
body.ed-story .floating-navbar {
  max-width: 1280px;
  margin: 0 auto;
  padding: 24px 32px;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 24px;
  background: transparent;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  transition: padding 300ms ease;
}
body.ed-story .nav-wrapper.at-top .floating-navbar { padding-top: 14px; padding-bottom: 14px; }

body.ed-story .nav-brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: 'Instrument Serif', serif;
  font-weight: 400;
  font-size: 30px;
  line-height: 1;
  letter-spacing: -0.6px;
  color: #0f172a;
  white-space: nowrap;
}
body.ed-story .nav-brand img { width: 28px; height: 28px; display: block; }
body.ed-story .nav-brand sup { font-family: 'Inter', sans-serif; font-size: 12px; margin-left: 2px; vertical-align: super; }

body.ed-story .nav-links-scroll { gap: 32px; overflow: visible; justify-self: center; }
body.ed-story .nav-pill {
  padding: 4px 0;
  border: 0;
  border-radius: 0;
  background: none;
  font-family: 'Inter', sans-serif;
  font-size: 14px;
  font-weight: 500;
  color: hsl(215, 25%, 32%);
  position: relative;
}
body.ed-story .nav-pill:hover { background: none; color: #0f172a; }
body.ed-story .nav-pill.active { background: none; border: 0; color: #0f172a; }
body.ed-story .nav-pill:not(.nav-pill-cta)::after {
  content: '';
  position: absolute;
  left: 0; right: 0; bottom: -2px;
  height: 1px;
  background: #0f172a;
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 250ms ease;
}
body.ed-story .nav-pill:not(.nav-pill-cta):hover::after,
body.ed-story .nav-pill.active:not(.nav-pill-cta)::after { transform: scaleX(1); }
body.ed-story .nav-pill-num { display: none; }

body.ed-story .nav-pill-cta {
  justify-self: end;
  background: #000000 !important;
  color: #ffffff !important;
  padding: 10px 24px;
  font-size: 14px;
  font-weight: 500;
  border-radius: 9999px;
  box-shadow: none;
  transition: transform 200ms ease-in-out;
}
body.ed-story .nav-pill-cta::after { display: none; }
body.ed-story .nav-pill-cta:hover { transform: scale(1.03); background: #000 !important; }

body.ed-story .nav-progress-bar { position: absolute; left: 0; right: 0; bottom: 0; margin: 0; height: 1px; border-radius: 0; }
body.ed-story .nav-progress-fill { background: #0f172a; }

/* ============================================================
   HERO  (full-bleed video, centered hierarchy)
   ============================================================ */
.ed-hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  background: hsl(201, 100%, 13%);
  isolation: isolate;
}
.ed-hero-video {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  z-index: -2;
}
/* Legibility: soft light scrim behind navy text, no heavy darkening */
.ed-hero::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
  background:
    radial-gradient(ellipse 70% 55% at 50% 48%, rgba(255, 255, 255, 0.60) 0%, rgba(255, 255, 255, 0.28) 55%, rgba(255, 255, 255, 0) 100%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.35) 0%, rgba(255, 255, 255, 0) 22%);
}
.ed-hero-inner {
  width: 100%;
  max-width: 1280px;
  padding: 132px 32px 64px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}
.ed-h1 {
  font-family: 'Instrument Serif', serif;
  font-weight: 400;
  font-size: 80px;
  line-height: 0.95;
  letter-spacing: -2.46px;
  color: #0f172a;
  max-width: 1080px;
  margin: 0;
}
.ed-h1 em { font-style: normal; color: hsl(215, 25%, 32%); }
.ed-lead {
  font-family: 'Inter', sans-serif;
  font-weight: 400;
  font-size: 18px;
  line-height: 1.625;
  color: hsl(215, 25%, 32%);
  max-width: 670px;
  margin: 28px auto 0;
}
.ed-cta-row { margin-top: 48px; display: flex; gap: 14px; flex-wrap: wrap; justify-content: center; }

.ed-metrics {
  margin-top: 64px;
  width: 100%;
  max-width: 920px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}
.ed-metric {
  text-align: left;
  padding: 20px 24px;
  background: rgba(255, 255, 255, 0.72);
  border: 1px solid rgba(15, 23, 42, 0.10);
  border-radius: 16px;
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}
.ed-metric small { display: block; font-size: 12px; font-weight: 500; color: hsl(215, 16%, 40%); letter-spacing: 0.02em; }
.ed-metric strong { display: block; margin: 6px 0 4px; font-family: 'Instrument Serif', serif; font-weight: 400; font-size: 38px; line-height: 1; letter-spacing: -1px; color: #0f172a; }
.ed-metric span { display: block; font-size: 13px; line-height: 1.5; color: hsl(215, 25%, 32%); }

/* ============================================================
   STORY BODY (chapters, steps, stage cards, footer)
   ============================================================ */
body.ed-story .chapter-section { padding: 120px 32px; border-top: 1px solid rgba(15, 23, 42, 0.08); }
body.ed-story .chapter-badge-soft {
  background: none;
  border: 0;
  padding: 0;
  font-family: 'Inter', sans-serif;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: hsl(215, 16%, 40%);
}
body.ed-story .chapter-title {
  font-family: 'Instrument Serif', serif;
  font-weight: 400;
  font-size: clamp(40px, 4.6vw, 64px);
  line-height: 0.98;
  letter-spacing: -1.8px;
  color: #0f172a;
}
body.ed-story .chapter-desc { font-size: 16px; line-height: 1.7; color: hsl(215, 25%, 32%); }

body.ed-story .story-step {
  background: #ffffff;
  border: 1px solid rgba(15, 23, 42, 0.10);
  border-radius: 16px;
  box-shadow: none;
}
body.ed-story .story-step.is-active {
  border-color: #0f172a;
  box-shadow: 0 24px 48px -24px rgba(15, 23, 42, 0.28);
}
body.ed-story .step-label {
  font-family: 'Inter', sans-serif;
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: hsl(215, 16%, 40%);
}
body.ed-story .step-signature-note {
  font-family: 'Instrument Serif', serif;
  font-style: italic;
  font-size: 1.15rem;
  letter-spacing: 0;
  text-transform: none;
  color: hsl(215, 25%, 32%);
}
body.ed-story .step-title {
  font-family: 'Instrument Serif', serif;
  font-weight: 400;
  font-size: 30px;
  line-height: 1.05;
  letter-spacing: -0.8px;
  color: #0f172a;
}
body.ed-story .step-text { font-size: 15px; line-height: 1.7; color: hsl(215, 25%, 32%); }
body.ed-story .step-highlight-pill {
  background: #f1f5f9;
  border: 1px solid rgba(15, 23, 42, 0.08);
  color: #0f172a;
}
body.ed-story .step-highlight-pill .highlight-val { font-family: 'Instrument Serif', serif; font-size: 1.3em; color: #0f172a; }

body.ed-story .visual-stage-card {
  border: 1px solid rgba(15, 23, 42, 0.10);
  border-radius: 20px;
  box-shadow: 0 30px 60px -30px rgba(15, 23, 42, 0.22);
}
body.ed-story .stage-topbar { background: #ffffff; border-bottom: 1px solid rgba(15, 23, 42, 0.08); }
body.ed-story .stage-tag-badge { background: #0f172a; color: #ffffff; font-weight: 500; letter-spacing: 0.04em; }
body.ed-story .stage-title { font-family: 'Instrument Serif', serif; font-weight: 400; font-size: 20px; letter-spacing: -0.3px; color: #0f172a; }
body.ed-story .stage-footer { background: #ffffff; border-top: 1px solid rgba(15, 23, 42, 0.08); color: hsl(215, 16%, 40%); }

body.ed-story [class*="chip"].active:not([data-hs]) {
  background: #000000 !important;
  color: #ffffff !important;
  border-color: #000000 !important;
  box-shadow: none !important;
}
body.ed-story [class*="chip"] { transition: transform 200ms ease-in-out, background 200ms ease; }
body.ed-story [class*="chip"]:hover { transform: scale(1.03); }

/* Conversion: video bookend */
body.ed-story .conversion-section {
  position: relative;
  overflow: hidden;
  padding: 140px 32px;
  background: hsl(201, 100%, 13%);
  isolation: isolate;
}
body.ed-story .conversion-section .ed-hero-video { z-index: -2; }
body.ed-story .conversion-section::after {
  content: '';
  position: absolute; inset: 0; z-index: -1;
  background: radial-gradient(ellipse 70% 70% at 50% 50%, rgba(255, 255, 255, 0.62) 0%, rgba(255, 255, 255, 0.2) 70%, rgba(255, 255, 255, 0) 100%);
}
body.ed-story .conversion-card {
  background: transparent;
  border: 0;
  box-shadow: none;
  padding: 0;
  max-width: 880px;
}
body.ed-story .conversion-icon { display: none; }
body.ed-story .conversion-title {
  font-family: 'Instrument Serif', serif;
  font-weight: 400;
  font-size: clamp(44px, 5.4vw, 72px);
  line-height: 0.95;
  letter-spacing: -2.2px;
  color: #0f172a;
}
body.ed-story .conversion-desc { font-size: 18px; line-height: 1.625; color: hsl(215, 25%, 32%); max-width: 640px; }
body.ed-story .btn-pill-coral,
body.ed-story .btn-pill-white {
  padding: 20px 56px;
  font-size: 16px;
  font-weight: 500;
  border-radius: 9999px;
  box-shadow: none;
  transition: transform 200ms ease-in-out, box-shadow 200ms ease-in-out;
}
body.ed-story .btn-pill-coral { background: #000000; color: #ffffff; border: 0; }
body.ed-story .btn-pill-white { background: rgba(255, 255, 255, 0.75); color: #0f172a; border: 1px solid rgba(15, 23, 42, 0.18); backdrop-filter: blur(10px); }
body.ed-story .btn-pill-coral:hover,
body.ed-story .btn-pill-white:hover { transform: scale(1.03); box-shadow: 0 10px 28px -8px rgba(0, 0, 0, 0.4); }
body.ed-story .btn-pill-coral:hover { background: #000000; }
body.ed-story .btn-pill-white:hover { background: #ffffff; }

body.ed-story .site-footer { background: #0f172a; border-top: 0; color: #cbd5e1; padding: 96px 32px; }
body.ed-story .footer-brand-title { font-family: 'Instrument Serif', serif; font-weight: 400; font-size: 34px; line-height: 1; letter-spacing: -1px; color: #ffffff; }
body.ed-story .footer-heading { color: #ffffff; font-weight: 500; letter-spacing: 0.12em; text-transform: uppercase; font-size: 12px; }
body.ed-story .footer-desc,
body.ed-story .footer-list li { color: #94a3b8; }
body.ed-story .footer-list strong { color: #e2e8f0; font-weight: 500; }

@media (max-width: 1100px) {
  body.ed-story .nav-links-scroll { display: none; }
  body.ed-story .floating-navbar { grid-template-columns: 1fr auto; }
}
@media (max-width: 768px) {
  .ed-h1 { font-size: 48px; letter-spacing: -1.5px; }
  .ed-lead { font-size: 16px; }
  .ed-metrics { grid-template-columns: 1fr; }
  .pill-btn.hero { padding: 18px 40px; }
  body.ed-story .floating-navbar { padding: 16px 20px; }
  body.ed-story .nav-brand { font-size: 24px; }
  body.ed-story .chapter-section { padding: 72px 20px; }
}

/* ============================================================
   DASHBOARD (dashboard_2.html)
   ============================================================ */
body.ed-dash .db-header {
  background: #0f172a;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  color: #ffffff;
}
body.ed-dash .db-brand { color: #ffffff; gap: 12px; }
body.ed-dash .db-brand-circle { background: transparent; box-shadow: none; width: 30px; height: 30px; }
body.ed-dash .db-brand-circle img { width: 30px; height: 30px; display: block; }
body.ed-dash .db-brand-title { font-family: 'Instrument Serif', serif; font-weight: 400; font-size: 26px; letter-spacing: -0.6px; line-height: 1; color: #ffffff; }
body.ed-dash .db-brand-title sup { font-family: 'Inter', sans-serif; font-size: 10px; margin-left: 2px; }
body.ed-dash .db-brand-sub { color: #94a3b8; font-weight: 400; font-size: 11px; margin-top: 3px; }

body.ed-dash .db-nav-btn {
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.22);
  color: #ffffff;
}
body.ed-dash .db-nav-btn:hover:not(:disabled) { background: #ffffff; color: #0f172a; }
body.ed-dash .db-nav-btn:disabled { opacity: 0.35; }
body.ed-dash .db-page-counter { color: #cbd5e1; font-family: 'Inter', sans-serif; }
body.ed-dash .db-btn-back {
  background: #ffffff;
  color: #000000;
  font-family: 'Inter', sans-serif;
  font-weight: 500;
  font-size: 14px;
  padding: 10px 24px;
  border-radius: 9999px;
  transition: transform 200ms ease-in-out;
}
body.ed-dash .db-btn-back:hover { background: #ffffff; transform: scale(1.03); }

body.ed-dash .db-tabbar { background: #ffffff; border-bottom: 1px solid rgba(15, 23, 42, 0.10); }
body.ed-dash .db-tab { font-family: 'Inter', sans-serif; font-weight: 500; font-size: 14px; color: hsl(215, 25%, 32%); }
body.ed-dash .db-tab:hover { color: #0f172a; }
body.ed-dash .db-tab.active { color: #0f172a; }
body.ed-dash .db-tab::after,
body.ed-dash .db-tab.active::after { background: #000000; }
body.ed-dash .db-tab-num,
body.ed-dash .db-tab.active .db-tab-num {
  background: none;
  color: hsl(215, 16%, 47%);
  font-family: 'Instrument Serif', serif;
  font-size: 18px;
  font-style: italic;
}
body.ed-dash .db-tab.active .db-tab-num { color: #0f172a; }

body.ed-dash .db-panel-label { font-family: 'Inter', sans-serif; font-weight: 500; letter-spacing: 0.14em; text-transform: uppercase; font-size: 11px; color: hsl(215, 16%, 40%); }
body.ed-dash .db-panel-title { font-family: 'Instrument Serif', serif; font-weight: 400; font-size: 26px; letter-spacing: -0.7px; line-height: 1.05; color: #0f172a; }
body.ed-dash .db-panel-footer { color: hsl(215, 16%, 40%); border-top: 1px solid rgba(15, 23, 42, 0.08); background: #ffffff; }
body.ed-dash .db-panel.active .db-panel-topbar,
body.ed-dash .db-panel.active .db-panel-chart { animation: fadeRise 0.8s ease-out both; }
body.ed-dash .db-panel.active .db-panel-chart { animation-delay: 0.2s; }

body.ed-dash [class*="chip"].active:not([data-hs]) {
  background: #000000 !important;
  color: #ffffff !important;
  border-color: #000000 !important;
  box-shadow: none !important;
}
body.ed-dash [class*="chip"] { transition: transform 200ms ease-in-out, background 200ms ease; }
body.ed-dash [class*="chip"]:hover { transform: scale(1.03); }

body.ed-dash .sankey-select:hover,
body.ed-dash .sankey-select:focus,
body.ed-dash .db-ms-trigger:hover,
body.ed-dash .db-ms-wrapper.open .db-ms-trigger { border-color: #0f172a; box-shadow: 0 0 0 2px rgba(15, 23, 42, 0.10); }
body.ed-dash .db-ms-btn-top { background: #0f172a; color: #ffffff; }
body.ed-dash .db-ms-btn-top:hover { background: #000000; color: #ffffff; }
'@ | Out-File -FilePath "assets/css/editorial.css" -Encoding utf8; (Get-Item assets/css/editorial.css).Length
